-- ============================================================================================
-- THE WRITE MAP, IN THE DATABASE WHERE THE BOARDS CAN READ IT
--
-- docs/phase-c/PHASE_C_EDGE_FUNCTION_WRITES.csv is generated by
-- scripts/checks/edge_function_writes.mjs from a real TypeScript AST, with every call site either
-- resolved or hand-resolved in edge-function-writes-exceptions.json. 0 unresolvable.
--
-- v_kernel_trigger_source_derived is a SQL view and cannot read a CSV, so the map lands here. The
-- committed file stays the source of truth and the two are compared, the same pairing the component
-- crosswalk already has -- three separate artefact catch-ups were needed on this branch alone.
--
-- unbounded = true means the function may write ANY table: its target comes from a request, a queue
-- row, or a config column. Those rows carry table_name '*' and must never CLEAR a source, because
-- "may write anything" is not "writes the table that discharges it".
--
-- This file only loads the map. It does NOT change routes_through_inbox; that is the next increment,
-- deliberately separate so the artefact can be reviewed before the measurement moves.
-- ============================================================================================

create table if not exists public.phase_c_edge_function_writes (
  edge_function text not null,
  table_name    text not null,
  write_kind    text not null,
  unbounded     boolean not null default false,
  loaded_at     timestamptz not null default now(),
  primary key (edge_function, table_name)
);

revoke all on public.phase_c_edge_function_writes from public;
grant select on public.phase_c_edge_function_writes to service_role;

truncate public.phase_c_edge_function_writes;
-- 22 Sep 2026 (customer_support, INT-03): the new SMS webhook. Three writes, all bounded — the
-- insert is capped by fn_rate_limit at 40/hour per sender before it is reached, the alert is
-- throttled to one per 30 minutes, and agent_runs is one row per accepted or refused webhook.
('sms_inbound','sms_messages','insert',false),
('sms_inbound','agent_runs','insert',false),
('sms_inbound','founder_alerts','insert',false),
('sms_inbound','ai_rate_limit','rpc:fn_rate_limit',false),
('voice_otp_capture','agent_runs','insert',false),
('vt_scan','agent_actions','insert',false),
('vt_scan','agent_runs','insert+update',false),
('vt_scan','notifications','insert',false),
('vt_scan','security_events','insert',false),
('vt_scan','vt_results','insert',false),
('wa_inbound','agent_runs','insert+rpc:fn_founder_apply_setting+rpc:fn_supplier_apply_change',false),
('wa_inbound','app_secrets','rpc:fn_founder_apply_setting',false),
('wa_inbound','channel_directive','rpc:fn_supplier_apply_change',false),
('wa_inbound','decision_policy','rpc:fn_founder_apply_setting',false),
('wa_inbound','doc_reviews','insert',false),
('wa_inbound','founder_alerts','insert',false),
('wa_inbound','founder_directive','rpc:fn_founder_apply_setting',false),
('wa_inbound','leads','update',false),
('wa_inbound','notifications','insert',false),
('wa_inbound','quotes','rpc:fn_supplier_apply_change',false),
('wa_inbound','wa_inbound_seen','insert',false),
('wa_inbound','wa_messages','insert',false),
('wa_optin_set','customers','update',false),
('wa_optin_set','leads','update',false),
('wa_template_setup','app_secrets','update',false),
('wa_templates_watch','agent_runs','insert',false),
('wa_templates_watch','app_secrets','upsert',false),
('wa_templates_watch','notifications','insert',false),
('workflow_dispatch','agent_runs','insert',false),
('workflow_dispatch','workflow_run','rpc:fn_workflow_step_done',false),
('workflow_dispatch','workflow_step_run','rpc:fn_workflow_step_claim+rpc:fn_workflow_step_done+rpc:fn_workflow_step_release',false),
('yello_scrape','yello_staging','update+upsert',false),
('ai_gateway','*','unbounded',true),
('customer_portal','*','unbounded',true),
('cos_execute','*','unbounded',true),
('dept_plan','*','unbounded',true),
('exec_agents','*','unbounded',true),
('os_api','*','unbounded',true);

do $wm$
declare n bigint; u bigint;
begin
  select count(*) into n from public.phase_c_edge_function_writes;
  select count(*) into u from public.phase_c_edge_function_writes where unbounded;
  if n <> 464 then
    raise exception 'expected 464 write-map rows, loaded %', n using errcode='23514';
  end if;
  raise notice 'write map loaded: % rows, % unbounded', n, u;
end $wm$;
